def generate(seed):
    r = random.Random(seed)
    rows = list(itertools.permutations('1234'))
    while True:
        g = [list(r.choice(rows))]
        ok = True
        for _ in range(3):
            cand = [p for p in rows if all(all(p[j] != row[j] for row in g) for j in range(4))]
            if not cand:
                ok = False
                break
            g.append(list(r.choice(cand)))
        if ok:
            break
    flat = ''.join(''.join(row) for row in g)
    keep = set(r.sample(range(16), r.randint(6, 8)))
    out = ''.join(flat[i] if i in keep else '.' for i in range(16))
    return '/'.join(out[i:i + 4] for i in range(0, 16, 4))

